    private static func decode<T: FixedWidthInteger>(_ base64: String, as type: T.Type) -> [T] {
        guard let data = Data(base64Encoded: base64.filter { !$0.isWhitespace }) else { return [] }
        return data.withUnsafeBytes { raw in
            (0..<(raw.count / MemoryLayout<T>.size)).map { T(littleEndian: raw.loadUnaligned(fromByteOffset: $0 * MemoryLayout<T>.size, as: T.self)) }
        }
    }
